export function createHandler({ store, publisher }) {
  return async function handler(event) {
    return { processed: false, duplicate: false };
  };
}

import assert from "node:assert/strict";
import { createHandler } from "./handler.js";

function fixtures() {
  const claimed = new Set();
  const published = [];
  let failNext = false;
  return {
    claimed,
    published,
    store: {
      async claim(id) {
        if (claimed.has(id)) return false;
        claimed.add(id);
        return true;
      },
      async release(id) {
        claimed.delete(id);
      },
    },
    publisher: {
      async publish(event) {
        if (failNext) {
          failNext = false;
          throw new Error("downstream unavailable");
        }
        published.push(event.eventId);
      },
    },
    failOnce() {
      failNext = true;
    },
  };
}

const first = fixtures();
const firstHandler = createHandler(first);
assert.deepEqual(await firstHandler({ eventId: "evt-1" }), { processed: true, duplicate: false, eventId: "evt-1" });
assert.deepEqual(await firstHandler({ eventId: "evt-1" }), { processed: false, duplicate: true, eventId: "evt-1" });
assert.deepEqual(first.published, ["evt-1"]);

const concurrent = fixtures();
const concurrentHandler = createHandler(concurrent);
const results = await Promise.all([
  concurrentHandler({ eventId: "evt-2" }),
  concurrentHandler({ eventId: "evt-2" }),
]);
assert.equal(results.filter((result) => result.processed).length, 1);
assert.equal(concurrent.published.length, 1);

const retry = fixtures();
const retryHandler = createHandler(retry);
retry.failOnce();
await assert.rejects(() => retryHandler({ eventId: "evt-3" }), /downstream unavailable/);
assert.equal(retry.claimed.has("evt-3"), false);
assert.equal((await retryHandler({ eventId: "evt-3" })).processed, true);

await assert.rejects(() => retryHandler({}), /eventId/);
console.log("lambda idempotency contract passed");
